+  let jobs = new Map();
+  let mutation = Promise.resolve();
+  let drainPromise = null;
+
+  function checkpoint() {
+    return { version: 1, jobs: [...jobs.values()].sort((a, b) => a.id.localeCompare(b.id)).map(j => ({ ...j, dependsOn: [...j.dependsOn] })) };
+  }
+  function validateLoaded(value) {
+    if (!value || value.version !== 1 || !Array.isArray(value.jobs)) throw new Error('corrupt scheduler checkpoint');
