+        ids.add(item.id);
+        additions.push({ id: item.id, dependsOn: [...deps], payload: item.payload === undefined ? null : jsonCopy(item.payload, `payload for ${item.id}`), status: 'pending', attempt: 0 });
+      }
+      const all = new Map(jobs); for (const job of additions) all.set(job.id, job);
+      for (const job of additions) for (const dep of job.dependsOn) if (!all.has(dep)) throw new TypeError(`unknown dependency: ${dep}`);
+      const visiting = new Set(), visited = new Set();
+      function visit(id) { if (visiting.has(id)) throw new TypeError('dependency cycle'); if (visited.has(id)) return; visiting.add(id); for (const d of all.get(id).dependsOn) visit(d); visiting.delete(id); visited.add(id); }
